begin;
create temp table homework_file_qa as select gen_random_uuid() as school,gen_random_uuid() as teacher,gen_random_uuid() as teacher_auth,gen_random_uuid() as parent_auth,gen_random_uuid() as guardian,gen_random_uuid() as class1,gen_random_uuid() as class2,gen_random_uuid() as student,gen_random_uuid() as hw1,gen_random_uuid() as hw2,gen_random_uuid() as file1,gen_random_uuid() as file2;
grant select on homework_file_qa to authenticated;
insert into institutions(id,name,status) select school,'Isolated homework files QA','trial' from homework_file_qa;
insert into auth.users(id,email,raw_app_meta_data) select parent_auth,'isolated-parent-'||parent_auth::text||'@example.invalid','{}'::jsonb from homework_file_qa;
insert into school_users(id,institution_id,email,role,status,auth_user_id) select teacher,school,'isolated-teacher@example.invalid','teacher','active',teacher_auth from homework_file_qa;
insert into school_classes(id,institution_id,name,section,academic_year) select class1,school,'QA One','A','2026-27' from homework_file_qa union all select class2,school,'QA Two','B','2026-27' from homework_file_qa;
insert into school_students(id,institution_id,class_id,admission_number,name,status) select student,school,class1,'QA-HW-ONLY','Isolated QA Student','active' from homework_file_qa;
insert into school_teacher_assignments(institution_id,school_user_id,class_id,assignment_type,subject,active,can_view_roster,can_take_attendance,can_assign_homework,can_enter_marks) select school,teacher,class1,'class_teacher','',true,true,true,true,false from homework_file_qa;
insert into school_homework(id,institution_id,class_id,subject,title,created_by) select hw1,school,class1,'Maths','QA task one',teacher from homework_file_qa union all select hw2,school,class2,'Maths','QA task two',teacher from homework_file_qa;
insert into school_guardians(id,institution_id,auth_user_id,email,status) select guardian,school,parent_auth,'isolated-parent@example.invalid','active' from homework_file_qa;
insert into school_guardian_students(guardian_id,institution_id,student_id,relationship) select guardian,school,student,'guardian' from homework_file_qa;
select set_config('request.jwt.claims',jsonb_build_object('sub',teacher_auth,'role','authenticated')::text,true) from homework_file_qa;
set local role authenticated;
insert into school_homework_files(id,homework_id,institution_id,storage_path,name,mime,size) select file1,hw1,school,school::text||'/'||hw1::text||'/'||file1::text||'.pdf','homework.pdf','application/pdf',123 from homework_file_qa;
insert into storage.objects(bucket_id,name,owner_id) select 'school-homework',school::text||'/'||hw1::text||'/'||file1::text||'.pdf',teacher_auth::text from homework_file_qa;
do $$ begin begin insert into school_homework_files(id,homework_id,institution_id,storage_path,name,mime,size) select file2,hw2,school,school::text||'/'||hw2::text||'/'||file2::text||'.pdf','not-authorized.pdf','application/pdf',123 from homework_file_qa; raise exception 'Unassigned homework upload was accepted'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',parent_auth,'role','authenticated')::text,true) from homework_file_qa;
set local role authenticated;
do $$ declare n integer; begin select count(*) into n from school_homework_files where institution_id=(select school from homework_file_qa); if n<>1 then raise exception 'Parent could not read own class attachment'; end if; select count(*) into n from storage.objects where bucket_id='school-homework' and name like (select school::text||'/%' from homework_file_qa); if n<>1 then raise exception 'Parent could not read own private object'; end if; begin insert into school_homework_files(id,homework_id,institution_id,storage_path,name,mime,size) select file2,hw1,school,school::text||'/'||hw1::text||'/'||file2::text||'.pdf','parent-upload.pdf','application/pdf',123 from homework_file_qa; raise exception 'Parent uploaded homework'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
set local role authenticated;
select jsonb_build_object('unrelated_attachment_rows',(select count(*) from school_homework_files where institution_id=(select school from homework_file_qa)),'unrelated_file_objects',(select count(*) from storage.objects where bucket_id='school-homework' and name like (select school::text||'/%' from homework_file_qa)),'assigned_teacher_and_parent_checks','passed') as verification;
rollback;
